    case .notFound(let val):
        encodeVarint(UInt64(0), into: &buffer)
        encodeString(val, into: &buffer)
    case .parseError(let val):
        encodeVarint(UInt64(1), into: &buffer)
        encodeString(val, into: &buffer)
    case .ioError(let val):
        encodeVarint(UInt64(2), into: &buffer)
        encodeString(val, into: &buffer)
    }
}
// MARK: - TaskService Client

public protocol TaskServiceCaller {
    ///  Return all tasks in the vault.
    func listTasks() async throws -> [Task]
    ///  Execute a query and return matching tasks sorted by the query's sort.
    func executeQuery(query: Query) async throws -> [Task]
    ///  Compute the urgency score for a single task.
    func urgencyScore(task: Task) async throws -> Int32
    ///  Create a new task. Returns the created task with generated id/dates filled in.
    func createTask(task: Task) async throws -> Result<Task, VaultError>
    ///  Update an existing task. Returns the updated task.
    func updateTask(task: Task) async throws -> Result<Task, VaultError>
    ///  Mark a task complete. Handles recurrence logic and sets completedDate.
    func completeTask(title: String) async throws -> Result<Task, VaultError>
    ///  Delete a task by title.
    func deleteTask(title: String) async throws -> Result<Void, VaultError>
    ///  Search tasks by text query (uses FTS5 index).
    func searchTasks(query: String) async throws -> [Task]
    ///  Get tasks assigned to a specific user.
    func tasksForUser(username: String) async throws -> [Task]
}

